  $requests=appDb()->query("SELECT r.id,r.tenant_id,r.plan_id,r.note,r.created_at,t.name company_name,sp.name plan_name,sp.monthly_price,sp.currency,u.name requester_name,u.email requester_email FROM plan_upgrade_requests r JOIN tenants t ON t.id=r.tenant_id JOIN subscription_plans sp ON sp.id=r.plan_id JOIN users u ON u.id=r.requested_by WHERE r.status='pending' ORDER BY r.created_at ASC")->fetchAll();
 }else{
  $q=appDb()->prepare("SELECT plan_id FROM plan_upgrade_requests WHERE tenant_id=? AND status='pending'");$q->execute([(int)$_SESSION['user']['tenant_id']]);$myPending=array_map('intval',$q->fetchAll(PDO::FETCH_COLUMN));
 }
}catch(Throwable $e){}
